// Scale any overflowing images, exclude http content.
if (!browser.contentDocument.URL.startsWith("http")) {
  const adjustImg = img => {
    img.toggleAttribute("overflowing", img.naturalWidth > img.clientWidth);
  };
  for (const img of browser.contentDocument.images) {
    // No zooming for children of clickable links.
    if (img.closest("[href]")) {
      continue;
    }
    img.toggleAttribute("shrinktofit", true);
    if (!img.complete) {
      img.addEventListener("load", event => adjustImg(event.target), {
        once: true,
      });
    } else {
      adjustImg(img);
    }

for (const image of msgDoc.querySelectorAll("img")) {
  imageIds.push(image);
  const imageId = imageIds.indexOf(image);
  Assert.lessOrEqual(
    image.clientWidth,
    messageDisplayWidth,
    `Image ${imageId} should be resized to fit into the message display`
  );
  const isInLink = image.closest("[href]");
  Assert.equal(
    image.hasAttribute("shrinktofit"),
    !isInLink,
    `Image ${imageId} should have correct shrinktofit attribute state`
  );
  if (image.naturalWidth > messageDisplayWidth && !isInLink) {
    Assert.ok(
      image.hasAttribute("overflowing"),
      `Image ${imageId} should be marked as overflowing`
    );
  } else {
    Assert.ok(
      !image.hasAttribute("overflowing"),
      `Image ${imageId} should not be marked as overflowing`
    );

onClick(event) {
  const { button, target } = event;

  // Is this an image that we might want to scale?
  if (button == 0 && HTMLImageElement.isInstance(target) && target.src) {
    // Make sure it loaded successfully. No action if not or a broken link.
    const req = target.getRequest(Ci.nsIImageLoadingContent.CURRENT_REQUEST);
    if (!req || req.imageStatus & Ci.imgIRequest.STATUS_ERROR) {
      return;
    }

    // Is it an image?
    if (target.localName == "img" && target.hasAttribute("overflowing")) {
      event.preventDefault();
      target.toggleAttribute("shrinktofit");
    }

for (const img of doc.querySelectorAll(
  "img:is([shrinktofit],[overflowing])"
)) {
  if (img.closest("[href]")) {
    continue;
  }
  if (!img.complete) {
    img.addEventListener("load", event => adjustImg(event.target), {
      once: true,
    });
  } else {
    adjustImg(img);
  }
}
